use crate::aap::caps::{http_client, notifier};
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the current wall-clock time.
        let seconds = wall_clock::now().seconds;

        // HTTPClient: the one permitted fetch. A transport failure is a value
        // and counts as zero characters; a URL outside the allowlist traps at
        // the boundary, which is the host's decision and not ours to catch.
        let (fetched, fetch_ok) = match http_client::fetch(&feed_url) {
            Ok(body) => (u32::try_from(body.chars().count()).unwrap_or(u32::MAX), true),
            Err(_) => (0u32, false),
        };

        // Notifier: the message is built only from values this node computed.
        // The fetched body is untrusted and is never put into the notification.
        let message = if fetch_ok {
            format!("heartbeat: time={}s fetched={} chars", seconds, fetched)
        } else {
            format!("heartbeat: time={}s fetch failed", seconds)
        };

        let notified = notifier::notify(&message);

        // Contract: ensures notified == true. If the channel refused the
        // notification, there is no honest output that satisfies the contract,
        // so trap rather than return a violating or fabricated report.
        if !notified {
            panic!("heartbeat: notification was not accepted");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
